-- Preserve the approval baseline of older handovers and reject unavailable cover tasks.
update public.work_handovers set created_by=coalesce(created_by,owner_id),approved_version=case when status='approved' then coalesce(approved_version,version) else approved_version end,approved_by=case when status='approved' then coalesce(approved_by,reviewer_id) else approved_by end,approved_at=case when status='approved' then coalesce(approved_at,updated_at) else approved_at end where not structured; do $$declare definition text;begin select pg_get_functiondef('private.handover_workspace(text,uuid,jsonb)'::regprocedure) into definition;definition:=replace(definition,'elsif operation=''share'' then','if not found and not exists(select 1 from public.actions where id=itemid and owner_id=h.owner_id and company_id=c and status=''done'' and deleted_at is null) then raise check_violation using message=''This task is no longer available for cover'';end if; elsif operation=''share'' then');execute definition;end$$;
